import type { Metadata } from 'next';
import type { ReactNode } from 'react';
import './globals.css';

export const metadata: Metadata = {
  title: 'Membership | Bike Repair Co-op',
  description: 'Stands, tools and know-how, free on Saturdays.',
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

:root {
  --bg: #0B0414;
  --surface: #140A24;
  --text: #F4F0FF;
  --primary: #7C5CFF;
  --accent: #22D3EE;
  --font-ui: Inter, system-ui, sans-serif;
  --font-display: Inter, system-ui, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-ui);
  line-height: 1.5;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

export type Plan = {
  id: string;
  name: string;
  blurb: string;
  monthly: string;
  yearly: string;
};

// All figures below are placeholders: replace with the co-op's real pricing.
export const PLANS: Plan[] = [
  {
    id: 'open-workshop',
    name: '[placeholder: plan name]',
    blurb: 'Bring your bike and use our stands and tools with a volunteer beside you.',
    monthly: '[placeholder: monthly price]',
    yearly: '[placeholder: yearly price]',
  },
  {
    id: 'learn-basics',
    name: '[placeholder: plan name]',
    blurb: 'Flats, brakes and gears: learn the fixes you will use every week.',
    monthly: '[placeholder: monthly price]',
    yearly: '[placeholder: yearly price]',
  },
];

'use client';

import { useState } from 'react';
import { PLANS } from '@/lib/plans';
import styles from './PricingPlans.module.css';

type Billing = 'monthly' | 'yearly';

export default function PricingPlans() {
  const [billing, setBilling] = useState<Billing>('monthly');
  const options: { value: Billing; label: string }[] = [
    { value: 'monthly', label: 'Monthly' },
    { value: 'yearly', label: 'Yearly' },
  ];

  return (
    <div>
      <div className={styles.toggle} role="group" aria-label="Billing period">
        {options.map((o) => (
          <button
            key={o.value}
            type="button"
            aria-pressed={billing === o.value}
            className={styles.toggleBtn}
            onClick={() => setBilling(o.value)}
          >
            {o.label}
          </button>
        ))}
      </div>

      <ul className={styles.grid}>
        {PLANS.map((p) => (
          <li key={p.id} className={styles.card}>
            <h3 className={styles.name}>{p.name}</h3>
            <p>{p.blurb}</p>
            <p className={styles.price} aria-live="polite">
              {billing === 'monthly' ? p.monthly : p.yearly}
              <span className={styles.per}>
                {billing === 'monthly' ? ' per month' : ' per year'}
              </span>
            </p>
          </li>
        ))}
      </ul>
    </div>
  );
}

.toggle {
  display: inline-flex;
  background: var(--surface);
  border: 1px solid var(--primary);
  border-radius: 999px;
  padding: 4px;
  margin-bottom: 1.5rem;
}

.toggleBtn {
  font: inherit;
  color: var(--text);
  background: transparent;
  border: 0;
  border-radius: 999px;
  padding: 0.5rem 1.25rem;
  min-height: 44px;
  cursor: pointer;
  transition: background 0.2s;
}

.toggleBtn[aria-pressed='true'] {
  background: #5B3CE0;
  font-weight: 600;
}

.grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
}

.card {
  background: var(--surface);
  border: 1px solid #2c1d4a;
  border-radius: 16px;
  padding: 1.5rem;
}

.name {
  margin: 0 0 0.5rem;
  font-family: var(--font-display);
  color: var(--accent);
}

.price {
  font-size: 1.25rem;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.per {
  font-size: 0.9rem;
  font-weight: 400;
}

import PricingPlans from '@/components/PricingPlans';
import styles from './page.module.css';

export default function Page() {
  return (
    <main className={styles.main}>
      <header className={styles.hero}>
        <h1 className={styles.title}>Fix your bike, together</h1>
        <p className={styles.sub}>Stands, tools and know-how, free on Saturdays.</p>
      </header>
      <section aria-labelledby="plans-heading">
        <h2 id="plans-heading" className={styles.heading}>Membership</h2>
        <PricingPlans />
      </section>
    </main>
  );
}

.main {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
}

.hero {
  padding: 2rem 0;
}

.title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 8vw, 3.5rem);
  line-height: 1.1;
  margin: 0 0 1rem;
}

.sub {
  font-size: 1.125rem;
  max-width: 40ch;
  margin: 0;
}

.heading {
  font-family: var(--font-display);
  margin: 2rem 0 1rem;
}
